import React from "react";
import { Box, Typography } from "@mui/material";

const ResultsPage = () => {
  return (
    <Box
      sx={{
        flexGrow: 1,
        p: 3,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        backgroundColor: "rgba(100, 200, 225, 0.3)",
        minHeight: "100vh",
      }}
    >
      <Typography variant="h4" fontWeight="bold">
        Election Results
      </Typography>
    </Box>
  );
};

export default ResultsPage;
